"""Offline contracts for the reviewed inline lifecycle and exact generated bytes."""
from copy import deepcopy
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest

import historical_studio_npm_continuation as lifecycle
import prepare_maintenance_build as maintenance
import product_release_metadata as metadata
import prove_historical_studio_npm_pair as historical
import prove_studio_npm_pair as npm


class HistoricalLifecycleContracts(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix='historical npm fixture ')
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name).resolve()

    def manifest(self, line='3.8', *, original=False):
        row = lifecycle.CONTINUATIONS[line]
        return maintenance.git_bytes(maintenance.ROOT, row['parent' if original else 'commit'], lifecycle.PATH)

    def write(self, root, payload):
        for name, data in payload.items():
            target = root / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)

    def layout(self, name, *, workspace=False, nested=False):
        root = self.root / name
        wrapper = root / ('wrappers/react-wrapper' if workspace else 'node_modules/' + npm.REACT)
        wasm = (wrapper if nested else root) / 'node_modules' / npm.WASM
        self.write(wrapper, {'package.json': self.manifest(), 'dist/main.js': b'export const fixture = true;'})
        payload = {'package.json': json.dumps({'name': npm.WASM, 'version': '3.8.999'}).encode(),
                   '_content/fixture/asset.js': b'asset', '_framework/runtime.wasm': b'\x00asm',
                   'appsettings.json': b'{"fixture":true}'}
        self.write(wasm, payload)
        return root, wrapper, wasm, payload

    def run_copy(self, wrapper, *, success=True):
        script = json.loads((wrapper / 'package.json').read_bytes())['scripts']['copy:elsa-studio-wasm']
        result = subprocess.run(script, cwd=wrapper, shell=True, env=os.environ,
                                capture_output=True, text=True, timeout=60)
        self.assertEqual(success, result.returncode == 0, result.stderr)

    def archives(self, root, wrapper, wasm):
        return {npm.WASM: (root / 'wasm.tgz', {'inventory': npm.files(wasm), 'version': '3.8.999',
                    'sha512_integrity': 'sha512-fixture'}),
                npm.REACT: (root / 'react.tgz', {'inventory': npm.files(wrapper)})}

    def test_exact_two_registered_source_deltas_and_eight_explicit_cells(self):
        catalog = maintenance.load_candidates()
        candidates = {row['commit']: row for row in catalog['candidates']}
        for line, selected in lifecycle.CONTINUATIONS.items():
            with self.subTest(line=line):
                row, parent = candidates[selected['commit']], candidates[selected['parent']]
                self.assertEqual(self.manifest(line), lifecycle.corrected_manifest(self.manifest(line, original=True)))
                lifecycle.verify_delta(row, parent, row['delta'][0], self.manifest(line, original=True), self.manifest(line))
                admitted = next(item for item in maintenance.registered_core_candidates(maintenance.load_register())
                                if item['commit'] == row['commit'])
                maintenance.verify_core_candidate(maintenance.ROOT, admitted)
                self.assertEqual(selected['commit'], metadata.DESCENDANTS[('studio', line)])
                self.assertEqual(0, subprocess.run(['git', 'merge-base', '--is-ancestor', selected['commit'], 'HEAD'],
                    cwd=maintenance.ROOT, capture_output=True).returncode)
        self.assertEqual(8, len(catalog['rehearsal_sources']))
        self.assertEqual({row['commit'] for row in lifecycle.CONTINUATIONS.values()},
                         {row['commit'] for row in catalog['rehearsal_sources']
                          if row['product'] == 'studio' and candidates[row['commit']]['kind'] == 'maintenance'})

    def test_protected_path_exception_rejects_other_identity_and_payload_changes(self):
        candidates = {row['commit']: row for row in maintenance.load_candidates()['candidates']}
        selected = lifecycle.CONTINUATIONS['3.8']
        row, parent = candidates[selected['commit']], candidates[selected['parent']]
        before, after = self.manifest(original=True), self.manifest()
        mutations = [lambda r: r.update(product='extensions'), lambda r: r.update(line='3.9'),
                     lambda r: r.update(commit=selected['parent']), lambda r: r.update(tree='f' * 40),
                     lambda r: r.update(parents=[lifecycle.CONTINUATIONS['3.9']['parent']]),
                     lambda r: r['delta'].append(deepcopy(r['delta'][0])),
                     lambda r: r['delta'][0].update(path='src/other/package.json'),
                     lambda r: r['delta'][0]['after'].update(blob='f' * 40)]
        for mutate in mutations:
            wrong = deepcopy(row); mutate(wrong)
            with self.subTest(row=wrong), self.assertRaises(ValueError):
                lifecycle.verify_delta(wrong, parent, wrong['delta'][0], before, after)
        for change in (lambda p: p.update(version='9.0.0'), lambda p: p.update(files=['dist', 'public']),
                       lambda p: p['dependencies'].update({npm.WASM: '9.0.0'}),
                       lambda p: p['scripts'].update(postinstall='true')):
            package = json.loads(after); change(package)
            with self.subTest(package=package), self.assertRaises(ValueError):
                lifecycle.verify_delta(row, parent, row['delta'][0], before, json.dumps(package).encode())

    def test_node22_is_the_fixture_runtime(self):
        result = subprocess.run(['node', '--version'], check=True, capture_output=True, text=True)
        self.assertTrue(result.stdout.startswith('v22.'), result.stdout)

    def test_workflow_runs_offline_contracts_with_node22_in_both_modes(self):
        workflow = (maintenance.ROOT / '.github/workflows/product-release-plan.yml').read_text()
        self.assertIn("node-version: '22'", workflow)
        for prefix in ('python3 -m unittest ', 'python3 -O -m unittest '):
            command = next(line for line in workflow.splitlines() if line.strip().startswith(prefix))
            self.assertIn('test_historical_studio_npm_continuation', command)

    def test_hoisted_scoped_nested_spaces_missing_public_and_idempotence(self):
        for name, options in [('hoisted workspace with spaces', {'workspace': True}),
                              ('scoped installed with spaces', {}), ('nested installed', {'nested': True})]:
            with self.subTest(name=name):
                root, wrapper, wasm, payload = self.layout(name, **options)
                if options.get('nested'):
                    self.write(root / 'node_modules' / npm.WASM,
                               {'package.json': payload['package.json'], 'appsettings.json': b'wrong ancestor'})
                self.assertFalse((wrapper / 'public').exists())
                before = npm.files(wasm)
                self.run_copy(wrapper)
                expected = {path: record for path, record in before.items() if path != 'package.json'}
                self.assertEqual(expected, npm.files(wrapper / 'public'))
                self.run_copy(wrapper)
                self.assertEqual(expected, npm.files(wrapper / 'public'))
                self.assertEqual(before, npm.files(wasm))

    def test_missing_dependency_or_required_payload_fails(self):
        for missing in ('dependency', '_content', '_framework', 'appsettings.json'):
            with self.subTest(missing=missing):
                _, wrapper, wasm, _ = self.layout('missing ' + missing.replace('/', '-'))
                target = wasm if missing == 'dependency' else wasm / missing
                shutil.rmtree(target) if target.is_dir() else target.unlink()
                self.run_copy(wrapper, success=False)

    def test_original_inline_script_cannot_produce_required_nested_assets_without_public(self):
        _, wrapper, wasm, _ = self.layout('original workspace', workspace=True)
        (wrapper / 'package.json').write_bytes(self.manifest(original=True))
        self.assertFalse((wrapper / 'public').exists())
        script = json.loads(self.manifest(original=True))['scripts']['copy:elsa-studio-wasm']
        subprocess.run(script, cwd=wrapper, shell=True, capture_output=True, timeout=15)
        # BSD cp fails at the missing destination; GNU cp can create a flattened
        # directory instead. Neither outcome has the three intended families.
        expected = {path: record for path, record in npm.files(wasm).items() if path != 'package.json'}
        self.assertNotEqual(expected, npm.files(wrapper / 'public'))

    def test_exact_installed_tar_bytes_plus_only_three_wasm_families(self):
        root, wrapper, wasm, _ = self.layout('valid')
        archives = self.archives(root, wrapper, wasm)
        self.run_copy(wrapper)
        receipt = historical.verify_installed(root, archives)
        self.assertEqual(3, len(receipt['assets']))
        self.assertNotIn(str(root), json.dumps(receipt))
        self.assertEqual({asset['path'] for asset in receipt['assets']},
                         {'public/_content/fixture/asset.js', 'public/_framework/runtime.wasm', 'public/appsettings.json'})

    def test_installed_extra_changed_missing_symlink_and_wasm_mutation_fail(self):
        for mutation in ('extra', 'changed', 'missing', 'symlink-file', 'symlink-public', 'symlink-package', 'wasm'):
            with self.subTest(mutation=mutation):
                root, wrapper, wasm, _ = self.layout(mutation)
                archives = self.archives(root, wrapper, wasm)
                self.run_copy(wrapper)
                target = wrapper / 'public/appsettings.json'
                if mutation == 'extra':
                    (wrapper / 'public/extra.js').write_bytes(b'extra')
                elif mutation == 'changed':
                    target.write_bytes(b'changed')
                elif mutation == 'missing':
                    target.unlink()
                elif mutation == 'wasm':
                    (wasm / 'appsettings.json').write_bytes(b'changed')
                else:
                    target = {'symlink-file': target, 'symlink-public': wrapper / 'public',
                              'symlink-package': wrapper}[mutation]
                    moved = target.with_name(target.name + '-real')
                    target.rename(moved); target.symlink_to(moved, target_is_directory=moved.is_dir())
                with self.assertRaises(npm.ProofError):
                    historical.verify_installed(root, archives)

    def test_missing_copy_family_or_tar_copy_collision_fails(self):
        for mutation in ('_content', '_framework', 'appsettings.json', 'collision'):
            with self.subTest(mutation=mutation):
                root, wrapper, wasm, _ = self.layout('inventory ' + mutation)
                archives = self.archives(root, wrapper, wasm)
                self.run_copy(wrapper)
                if mutation == 'collision':
                    archives[npm.REACT][1]['inventory']['public/appsettings.json'] = archives[npm.WASM][1]['inventory']['appsettings.json']
                else:
                    inventory = archives[npm.WASM][1]['inventory']
                    for path in list(inventory):
                        if path == mutation or path.startswith(mutation + '/'):
                            del inventory[path]
                with self.assertRaises(npm.ProofError):
                    historical.verify_installed(root, archives)


if __name__ == '__main__':
    unittest.main()
